import React, { Ref, useImperativeHandle, useMemo } from 'react';
import { format } from 'date-fns';
import { DayContentProps, Matcher } from 'react-day-picker';
import { StyledCalendar, StyledCalendarContainer } from './Calendar.styles';
import { CalendarProps, CalendarRef } from './Calendar.types';
import Caption from './components/Caption/Caption';
import Day from './components/Day/Day';
import { LegendBase } from './components/Legend/Legend.types';
import Legend from './components/Legend/Legend';
import 'react-day-picker/dist/style.css';
import { getTranslationsDate } from '../../utils';
import { setUTCHoursForDate } from './utils/setUTCHoursForDate';

type DateConfigHash = { [index: string]: LegendBase };

const Calendar = React.forwardRef(
  (
    {
      hightlightedDates = [],
      numberOfMonths = 1,
      legend = {
        orientation: 'vertical',
      },
      mode = 'single',
      onChange,
      customLocale,
      ...restProps
    }: CalendarProps,
    forwardedRef: Ref<CalendarRef>
  ): JSX.Element => {
    const [selection, setSelection] = React.useState<Matcher | Matcher[]>();
    const locale = getTranslationsDate(customLocale);

    const dateExtraConfig = useMemo(() => {
      let datesConfigHash: DateConfigHash = {};

      hightlightedDates.forEach((hightlightedDate) => {
        datesConfigHash = {
          ...datesConfigHash,
          ...hightlightedDate.dates.reduce(
            (acc, date) => ({
              ...acc,
              [format(date, 'dd-MM-yyyy')]: {
                caption: hightlightedDate.caption,
                theme: hightlightedDate.theme,
              },
            }),
            {}
          ),
        };
      });

      return datesConfigHash;
    }, [hightlightedDates]);

    const legends: LegendBase[] = hightlightedDates.map(({ theme, caption }) => ({
      theme,
      caption,
    }));

    const renderDayContent = (props: DayContentProps) => {
      const dateKey = format(props.date, 'dd-MM-yyyy');
      let aditionalProps = {};
      if (dateExtraConfig[dateKey]) {
        const { theme } = dateExtraConfig[dateKey];
        aditionalProps = { theme };
      }
      return <Day {...props} {...aditionalProps} />;
    };

    const isDateMultiple = useMemo(
      () => Array.isArray(selection) || selection === undefined,
      [selection]
    );

    useImperativeHandle(
      forwardedRef,
      () =>
        ({
          clearSelection: () => {
            setSelection?.(undefined);
          },
          changeSelection: (value: Matcher | Matcher[]) => {
            setSelection?.(value);
          },
        } as CalendarRef)
    );

    return (
      <StyledCalendarContainer ref={forwardedRef}>
        <StyledCalendar
          {...restProps}
          locale={locale}
          mode={mode}
          numberOfMonths={numberOfMonths}
          selected={!isDateMultiple && mode === 'multiple' ? undefined : selection}
          onSelect={(props: Matcher | Matcher[]) => {
            const selectedDate = setUTCHoursForDate(props);
            setSelection(selectedDate);
            onChange?.(selectedDate);
          }}
          showOutsideDays
          components={{
            DayContent: renderDayContent,
            Caption: (props) => <Caption {...props} />,
          }}
          formatters={{
            formatWeekdayName: (props) => format(props, 'EEE', { locale }),
          }}
          modifiersClassNames={{
            selected: 'hexa-ui-selected',
            day: 'hexa-ui-day',
            range_start: 'hexa-ui-range_start',
            range_middle: 'hexa-ui-range_middle',
            range_end: 'hexa-ui-range_end',
            today: 'hexa-ui-today',
          }}
        />
        {!!legends && <Legend captions={legends} orientation={legend.orientation} />}
      </StyledCalendarContainer>
    );
  }
);

export default Calendar;
